using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Text;
using System.Windows.Forms;
namespace Aster {
class RecoveryJob {
 public string Id,Title,Description,Exe,Arguments;public bool Admin;
 public static RecoveryJob[] All={
 new RecoveryJob{Id="image-check",Title="Check Windows image",Description="Quickly checks whether the Windows component store is already marked as damaged. Does not repair files.",Exe="dism.exe",Arguments="/Online /Cleanup-Image /CheckHealth",Admin=true},
 new RecoveryJob{Id="image-scan",Title="Scan Windows image",Description="Performs a deeper component-store scan without repairing it. May take several minutes.",Exe="dism.exe",Arguments="/Online /Cleanup-Image /ScanHealth",Admin=true},
 new RecoveryJob{Id="image-repair",Title="Repair Windows image",Description="Repairs the Windows component store. May download files from Windows Update. Keep your PC powered on until it finishes.",Exe="dism.exe",Arguments="/Online /Cleanup-Image /RestoreHealth",Admin=true},
 new RecoveryJob{Id="files-check",Title="Verify system files",Description="Checks protected Windows system files without replacing them. Use the log to see whether corruption was found.",Exe="sfc.exe",Arguments="/verifyonly",Admin=true},
 new RecoveryJob{Id="files-repair",Title="Repair system files",Description="Scans and replaces damaged protected system files. If image corruption is suspected, run Repair Windows image first. A restart may be needed afterward.",Exe="sfc.exe",Arguments="/scannow",Admin=true},
 new RecoveryJob{Id="disk-check",Title="Check system-drive filesystem",Description="Runs CHKDSK without repair switches. Does not schedule a reboot or attempt repairs. Files in use can affect the report.",Exe="chkdsk.exe",Arguments=Path.GetPathRoot(Environment.SystemDirectory).TrimEnd('\\'),Admin=true},
 new RecoveryJob{Id="dns-flush",Title="Flush DNS cache",Description="Clears cached DNS answers to help troubleshoot name-resolution problems. The cache rebuilds as you browse.",Exe="ipconfig.exe",Arguments="/flushdns",Admin=true},
 new RecoveryJob{Id="winsock-reset",Title="Reset Winsock",Description="Resets the Winsock catalog. Some VPN or networking software may need repair afterward. Save your work and restart Windows manually after reviewing the result.",Exe="netsh.exe",Arguments="winsock reset",Admin=true}
 };
 public static RecoveryJob Find(string id){return All.FirstOrDefault(j=>j.Id==id);}
 public string FileName{get{return Path.Combine(Environment.SystemDirectory,Exe);}}
}
class RepairWindow:Form {
 TextBox output;Label state;Process process;bool running;StringBuilder log=new StringBuilder();string path;RecoveryJob job;
 public RepairWindow(RecoveryJob value){job=value;Text="Aster Recovery · "+job.Title;Size=new Size(850,600);StartPosition=FormStartPosition.CenterScreen;BackColor=Color.FromArgb(20,26,34);ForeColor=Color.White;Font=new Font("Segoe UI",10);state=new Label{Dock=DockStyle.Top,Height=80,Padding=new Padding(16),Text=job.Title+"\r\n"+job.Exe+" "+job.Arguments};Controls.Add(state);output=new TextBox{Multiline=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Fill,ReadOnly=true,BackColor=Color.FromArgb(13,18,25),ForeColor=Color.FromArgb(182,221,219),Font=new Font("Consolas",10),BorderStyle=BorderStyle.None};Controls.Add(output);output.BringToFront();Shown+=(s,e)=>Run();FormClosing+=(s,e)=>{if(running){e.Cancel=true;MessageBox.Show(this,"This Windows tool is still running. Wait for it to finish before closing this window.");}};}
 void Append(string text){if(IsDisposed)return;if(InvokeRequired){BeginInvoke(new Action<string>(Append),text);return;}text=(text??"").Replace("\0","");log.AppendLine(text);output.AppendText(text+Environment.NewLine);}
 async void Run(){running=true;try{var dir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Pulse","RecoveryLogs");Directory.CreateDirectory(dir);path=Path.Combine(dir,DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+job.Id+".txt");Append(DateTime.Now+" · "+job.FileName+" "+job.Arguments);process=new Process{StartInfo=new ProcessStartInfo(job.FileName,job.Arguments){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true}};if(job.Exe=="sfc.exe")process.StartInfo.StandardOutputEncoding=Encoding.Unicode;process.OutputDataReceived+=(s,e)=>{if(e.Data!=null)Append(e.Data);};process.ErrorDataReceived+=(s,e)=>{if(e.Data!=null)Append(e.Data);};process.Start();process.BeginOutputReadLine();process.BeginErrorReadLine();await System.Threading.Tasks.Task.Run(()=>process.WaitForExit());Append("Tool finished. Exit code: "+process.ExitCode+". Review the output; completion does not by itself prove Windows is healthy.");state.Text="Finished · exit code "+process.ExitCode+"\r\nLog: "+path;}catch(Exception ex){Append("Could not complete: "+ex.Message);state.Text="Could not complete · review details below";}finally{running=false;if(path!=null){try{File.WriteAllText(path,log.ToString(),Encoding.UTF8);}catch(Exception ex){Append("Could not save log: "+ex.Message);}}if(process!=null)process.Dispose();}}
}
partial class MainWindow {
 void BuildRecovery(){sub.Text="Diagnose first. Repair only the part that needs it. Each tool explains its changes before it runs.";var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(0,8,0,8)};content.Controls.Add(flow);var intro=new Label{Text="WINDOWS REPAIR TOOLS\r\nAdministrator tools open in a separate progress window. Windows asks for permission.\r\nNo automatic reboot, file cleanup or registry tuning is performed.",ForeColor=muted,AutoSize=true,Margin=new Padding(0,0,0,20)};flow.Controls.Add(intro);
 foreach(var job in RecoveryJob.All){var j=job;var card=new Panel{Width=850,Height=104,BackColor=panel,Margin=new Padding(0,0,0,12)};var title=new Label{Text=j.Title,Location=new Point(14,10),AutoSize=true,Font=new Font("Segoe UI",11,FontStyle.Bold)};var desc=new Label{Text=j.Description,Location=new Point(14,38),Width=660,Height=62,ForeColor=muted};var run=Button("Open tool");run.Location=new Point(720,31);run.Click+=(s,e)=>LaunchRepair(j);card.Controls.AddRange(new Control[]{title,desc,run});flow.Controls.Add(card);}
 flow.Controls.Add(new Label{Text="WINDOWS RECOVERY SHORTCUTS",AutoSize=true,Margin=new Padding(0,18,0,12),ForeColor=cyan});
 AddShortcut(flow,"Restore points / protection","SystemPropertiesProtection.exe","");AddShortcut(flow,"System Restore wizard","rstrui.exe","");AddShortcut(flow,"Memory diagnostic (offers a restart)","mdsched.exe","");AddShortcut(flow,"Reliability history","perfmon.exe","/rel");AddShortcut(flow,"Event Viewer","eventvwr.exe","");AddShortcut(flow,"Disk Cleanup (choose what to remove)","cleanmgr.exe","");AddShortcut(flow,"Windows Update","ms-settings:windowsupdate","");AddShortcut(flow,"Windows troubleshooters","ms-settings:troubleshoot","");AddShortcut(flow,"Recovery settings","ms-settings:recovery","");
 var logs=Button("Open recovery logs");logs.Click+=(s,e)=>{string dir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Pulse","RecoveryLogs");Directory.CreateDirectory(dir);Process.Start(new ProcessStartInfo(dir){UseShellExecute=true});};flow.Controls.Add(logs);
 }
 void AddShortcut(FlowLayoutPanel p,string title,string exe,string args){var b=Button(title);b.Click+=(s,e)=>{try{Process.Start(new ProcessStartInfo(exe.StartsWith("ms-settings:")?exe:Path.Combine(Environment.SystemDirectory,exe),args){UseShellExecute=true});}catch(Exception ex){MessageBox.Show(this,ex.Message,"Could not open Windows tool");}};p.Controls.Add(b);}
 void LaunchRepair(RecoveryJob job){if(MessageBox.Show(this,job.Description+"\r\n\r\nCommand: "+job.Exe+" "+job.Arguments+"\r\n\r\nContinue and request administrator access?",job.Title,MessageBoxButtons.OKCancel,MessageBoxIcon.Information,MessageBoxDefaultButton.Button2)!=DialogResult.OK)return;try{Process.Start(new ProcessStartInfo(Application.ExecutablePath,"--repair "+job.Id){UseShellExecute=true,Verb="runas"});}catch(Exception ex){MessageBox.Show(this,ex.Message,"Tool not started");}}
 void BuildWallpaperLauncher(){sub.Text="Aura · a separate live wallpaper studio";var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,Padding=new Padding(10)};flow.Controls.Add(new Label{Text="Make the desktop yours.",AutoSize=true,Font=new Font("Segoe UI",24),Margin=new Padding(0,20,0,15)});flow.Controls.Add(new Label{Text="1,000 new animated variations, search, category filters, local media, playlists,\r\nclock overlays and automatic pause while gaming or using battery power.\r\n\r\nPreview first, then choose Apply to desktop in Aura.",ForeColor=muted,AutoSize=true,Margin=new Padding(0,0,0,20)});var b=Button("Open Aura Wallpaper");b.Click+=(s,e)=>{try{string folder=AppDomain.CurrentDomain.BaseDirectory;string exe=Path.Combine(folder,"AuraWallpaper.exe");if(!File.Exists(exe))throw new FileNotFoundException("AuraWallpaper.exe is missing. Extract the entire Aster ZIP, then try again.");Process.Start(new ProcessStartInfo(exe){WorkingDirectory=folder,UseShellExecute=true});}catch(Exception ex){MessageBox.Show(this,ex.Message,"Could not open Aura");}};flow.Controls.Add(b);content.Controls.Add(flow);}
}
}

